public class Account {
    private String owner;
    private long balance;

    // 1. Chaining: one master constructor owns validation.
    public Account(String owner) {
        this(owner, 0); // must be first line
    }

    public Account(String owner, long balance) {
        if (owner == null || owner.isBlank()) throw new IllegalArgumentException("owner required");
        if (balance < 0) throw new IllegalArgumentException("negative balance");
        // 2. Disambiguation: field vs parameter.
        this.owner = owner;
        this.balance = balance;
    }

    // 3. Fluent: return the same receiver for chaining.
    public Account deposit(long amount) {
        if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
        this.balance += amount;
        return this;
    }

    // 4. Self-passing: hand your identity to a collaborator.
    public void register(AuditLog log) {
        log.watch(this);
    }

    public long balance() {
        return this.balance; // explicit only for emphasis
    }
}

// BAD: 'this' escapes before fields are assigned.
class BadService {
    private final String endpoint;
    BadService(String endpoint, Registry r) {
        r.register(this); // observer sees endpoint == null
        this.endpoint = endpoint;
    }
}

// GOOD: factory constructs fully, then publishes.
class GoodService {
    private final String endpoint;
    private GoodService(String endpoint) { this.endpoint = endpoint; }
    static GoodService create(String endpoint, Registry r) {
        GoodService s = new GoodService(endpoint);
        r.register(s); // safe: construction complete
        return s;
    }
}
